def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target_buffer = 0.12 * bins
    ratio = np.where(bins > 0, remaining / (target_buffer + 1e-8), 0)
    score = -np.power(ratio - 1.0, 4)
    return np.where(remaining >= 0, score, -np.inf)
